const OFFERS = [
  { n: 'MÉGA PACK DÉPART', d: '3000 🪙 + 5 ❤️ + skin Néon', e: '🎁', old: '19,99 €', eur: '1,99 €', off: 90, coins: 3000, lives: 5, skin: 'neon', wide: true },
  { n: 'Recharge de vies', d: 'Remplit tes 5 ❤️', e: '❤️', coinPrice: 300, lives: 5 },
  { n: 'Coffre d\'or', d: '+1500 🪙', e: '👑', old: '9,99 €', eur: '2,99 €', off: 70, coins: 1500 }
];
const PACKS = [
  { n: 'Poignée', e: '🪙', coins: 500, eur: '0,99 €' }, { n: 'Sac', e: '💰', coins: 1200, eur: '1,99 €' },
  { n: 'Coffre', e: '🧰', coins: 3000, eur: '4,99 €' }, { n: 'Trésor', e: '🏆', coins: 8000, eur: '9,99 €', off: 50, old: '19,99 €' }
];
const SKINS = [
  { id: 'classic', n: 'Classique', coinPrice: 0, t: 'car', c: 'red' }, { id: 'neon', n: 'Néon', coinPrice: 800, t: 'van', c: 'green' },
  { id: 'pastel', n: 'Pastel', coinPrice: 500, t: 'bus', c: 'blue' }, { id: 'vintage', n: 'Vintage', coinPrice: 600, t: 'truck', c: 'orange' }
];
let shopTab = 'offers';

function renderShop() {
  document.querySelectorAll('.tab').forEach(t => t.classList.toggle('on', t.dataset.tab === shopTab));
  const box = $('shopCards'); box.innerHTML = '';
  const add = (html, cls, fn) => { const d = document.createElement('div'); d.className = 'card ' + (cls || ''); d.innerHTML = html;
    d.style.animationDelay = box.children.length * .06 + 's'; d.querySelector('.buy').onclick = fn; box.appendChild(d); };
  const rib = it => it.off ? `<div class="ribbon">-${it.off}%</div>` : '';
  const price = it => `${it.old ? `<span class="old">${it.old}</span>` : ''}<button class="buy press">${it.eur || '🪙 ' + it.coinPrice}</button>`;
  if (shopTab === 'offers') OFFERS.forEach(o => add(`${rib(o)}<div class="pic">${o.e}</div><h4>${o.n}</h4><p>${o.d}</p>${price(o)}`, o.wide ? 'wide' : '', () => buy(o)));
  if (shopTab === 'coins') PACKS.forEach(o => add(`${rib(o)}<div class="pic">${o.e}</div><h4>${o.coins} 🪙</h4><p>${o.n}</p>${price(o)}`, '', () => buy(o)));
  if (shopTab === 'skins') SKINS.forEach(k => {
    const own = S.owned.includes(k.id), on = S.skin === k.id;
    add(`<div class="pic skin-${k.id}">${miniVeh(k.t, k.c)}</div><h4>${k.n}</h4><p>${on ? 'Équipé ✔' : own ? 'Possédé' : 'Skin exclusif'}</p>
      <button class="buy press ${on ? 'off' : own ? '' : 'gold'}">${on ? 'ÉQUIPÉ' : own ? 'ÉQUIPER' : '🪙 ' + k.coinPrice}</button>`, '', () => {
      if (own) { S.skin = k.id; toast('Skin équipé : ' + k.n); }
      else if (S.coins >= k.coinPrice) { S.coins -= k.coinPrice; S.owned.push(k.id); S.skin = k.id; toast('Skin débloqué ! 🎉'); }
      else return toast('Pas assez de pièces 🪙');
      save(); vib(30); refreshHud(); renderShop(); });
    box.lastChild.querySelector('.pic').style.filter = '';
  });
}
function buy(o) {
  if (o.coinPrice) { if (S.coins < o.coinPrice) return toast('Pas assez de pièces 🪙'); S.coins -= o.coinPrice; }
  else toast('Achat simulé (démo) : ' + o.eur);
  if (o.coins) S.coins += o.coins;
  if (o.lives) S.lives = MAXLIVES;
  if (o.skin && !S.owned.includes(o.skin)) S.owned.push(o.skin);
  if (o.coinPrice) toast('Achat réussi ! ✅');
  save(); vib(40); refreshHud(); tickLives(); confetti(24); SFX.coin();
}
$('shopTabs').onclick = e => { const t = e.target.closest('.tab'); if (t) { shopTab = t.dataset.tab; renderShop(); } };

function renderRank() {
  const names = ['MegaDrift', 'ParkingPro', 'LuluBus', 'TurboTom', 'Zoé_77', 'Kenji', 'Nova'];
  const rows = names.map((n, i) => ({ n, lv: S.level + 14 - i * 3 })).concat([{ n: 'Toi 😎', lv: S.level, me: 1 }]).sort((a, b) => b.lv - a.lv);
  $('rankList').innerHTML = rows.map((r, i) => `<div class="row ${r.me ? 'me' : ''}">${['🥇', '🥈', '🥉'][i] || (i + 1) + '.'} ${r.n}<b>Niv. ${r.lv}</b></div>`).join('');
}
let worldPage = 0;                                                  // 24 niveaux par page
function renderWorld() {
  const per = 24, pages = Math.ceil(TOTAL / per); worldPage = Math.max(0, Math.min(pages - 1, worldPage));
  let h = '';
  for (let n = worldPage * per + 1; n <= Math.min(TOTAL, (worldPage + 1) * per); n++) {
    const b = S.best[n], st = b ? '⭐'.repeat(b.stars) : '';
    h += `<button class="node press ${n > S.level ? 'lock' : n === S.level ? 'cur' : ''}" data-n="${n}">${n > S.level ? '🔒' : n}<small style="display:block;font-size:9px">${st}</small></button>`;
  }
  h += `<button class="row press" data-page="-1" style="grid-column:span 2;justify-content:center">◀</button><button class="row press" data-page="1" style="grid-column:span 2;justify-content:center">▶ ${worldPage + 1}/${pages}</button>`;
  $('nodes').innerHTML = h;
}
$('nodes').onclick = e => {
  const pg = e.target.closest('[data-page]'); if (pg) { worldPage += +pg.dataset.page; return renderWorld(); }
  const b = e.target.closest('.node'); if (!b) return; const n = +b.dataset.n; n <= S.level ? startLevel(n) : toast('Niveau verrouillé 🔒');
};
$('optVib').onclick = () => { S.vib = !S.vib; save(); refreshHud(); vib(30); };
$('optSound').onclick = () => { S.sound = !S.sound; save(); refreshHud(); SFX.click(); };
$('optReset').onclick = () => { if (confirm('Tout réinitialiser ?')) { S = JSON.parse(JSON.stringify(DEF)); save(); refreshHud(); toast('Progression réinitialisée'); } };

/* ---------- 6. CATALOGUE DES MÉCANIQUES (système modulaire) ----------
   Pour ajouter une mécanique : ajoute une entrée ici (id, icône, texte du tutoriel, test de détection),
   puis gère son effet dans limits() / portalOpen() / refreshBadges(). Le tutoriel s'affiche tout seul
   la première fois qu'un niveau contient la mécanique (test(level) === true). */
const MECHS = [
  { id: 'blocks',     icon: '🚧', name: 'Cases bloquées',      art: '🚗 ➜ 🚧',      text: 'Ces cases sont bloquées : aucun véhicule ne peut les traverser.', test: L => L.blocks.length > 0 },
  { id: 'lock',       icon: '🔒', name: 'Cadenas',             art: '🔒🚙 ⟵ 🚗',    text: 'Un véhicule cadenassé ne bouge pas tant que le véhicule dont la couleur est sur la pastille n\'a pas quitté le plateau.', test: L => L.cars.some(c => c.lock >= 0) },
  { id: 'edge4',      icon: '↔️', name: 'Portails aux 4 bords', art: '🟥 🚗 🟦',     text: 'Un véhicule peut sortir par l\'un ou l\'autre bout de son axe, par le portail de sa couleur.', test: L => L.portals.some(p => p.s === 'xr' || p.s === 'yb') },
  { id: 'star',       icon: '⭐', name: 'Portail étoilé',      art: '⭐ ➜ 🚗🚙🚚',  text: 'Un portail étoilé accepte toutes les couleurs.', test: L => L.portals.some(p => p.kind === 1) },
  { id: 'frost',      icon: '❄️', name: 'Portail givré',       art: '❄️3 ➜ 🚗',     text: 'Un portail givré est fermé tant que le nombre de sorties indiqué n\'est pas atteint.', test: L => L.portals.some(p => p.kind === 2) },
  { id: 'oneway',     icon: '⬆️', name: 'Sens unique',         art: '🚗 ➜➜ ⛔⬅',    text: 'Ce véhicule ne peut avancer que dans le sens de la flèche. Impossible de revenir en arrière : réfléchis avant de glisser !', test: L => L.cars.some(c => c.ow !== 0) },
  { id: 'slow',       icon: '🐢', name: 'Véhicule lent',       art: '🐢🚚 1 case',  text: 'Un véhicule lent ne glisse que de quelques cases à la fois, et doit être tout près du bord pour sortir.', test: L => L.cars.some(c => c.sl > 0) },
  { id: 'exitafter',  icon: '🎯', name: 'Priorité',            art: '🎯🚗 ⟵ 🚙',    text: 'Ce véhicule peut bouger, mais ne peut sortir qu\'après la sortie du véhicule dont la couleur est sur la pastille.', test: L => L.cars.some(c => c.ea >= 0) },
  { id: 'lockn',      icon: '🔢', name: 'Cadenas à compteur',  art: '🔒2 ➜ 🚗🚗',   text: 'Ce cadenas s\'ouvre quand le nombre de véhicules indiqué est sorti.', test: L => L.cars.some(c => c.ln > 0) },
  { id: 'lockcolor',  icon: '🎨', name: 'Cadenas couleur',     art: '🔒🎨 ⟵ 🚗',    text: 'Ce cadenas s\'ouvre dès qu\'un véhicule de la couleur de la pastille est sorti.', test: L => L.cars.some(c => c.lc >= 0) },
  { id: 'fleeting',   icon: '⏳', name: 'Portail éphémère',    art: '⏳2 ➜ ✖',      text: 'Ce portail se ferme pour toujours après le nombre de sorties indiqué. Choisis bien qui l\'utilise !', test: L => L.portals.some(p => p.kind === 3) },
  { id: 'parity',     icon: '½',  name: 'Portail pair/impair', art: 'PAIR ⇄ IMP',   text: 'Ce portail s\'ouvre seulement quand le nombre de véhicules déjà sortis est pair (PAIR) ou impair (IMP).', test: L => L.portals.some(p => p.kind === 4) },
  { id: 'window',     icon: '🪟', name: 'Portail à fenêtre',   art: '1-3 ➜ 🚗',     text: 'Ce portail est ouvert seulement entre les deux nombres de sorties affichés.', test: L => L.portals.some(p => p.kind === 5) },
  { id: 'typeportal', icon: '🚌', name: 'Portail de type',     art: '🚌 ➜ 🚌',      text: 'Ce portail n\'accepte que le type de véhicule affiché : voiture, camionnette, camion ou bus.', test: L => L.portals.some(p => p.kind === 6) },
  { id: 'cyclic',     icon: '🌈', name: 'Portail caméléon',    art: '🟥🟦🟨🟩🟪🟧',  text: 'La couleur de ce portail change à chaque sortie, dans l\'ordre rouge, bleu, jaune, vert, violet, orange.', test: L => L.portals.some(p => p.kind === 7) }
];

/* ---------- 6b. BASE DE NIVEAUX : décodage (LEVEL_DB vient de levels-db.js) ----------
   Format d'un niveau : [w, h, coupsOptimaux, voitures, cases bloquées, portails]
   voiture : [type, couleur, c, r, vertical, lock, sensUnique, lent, prioritéAprès, cadenasCouleur, cadenasCompteur]
   portail : [bord, ligne, couleur, genre, p1, p2]  (genre 0 normal, 1 étoilé, 2 givré, 3 éphémère, 4 pair/impair, 5 fenêtre, 6 type, 7 caméléon) */
const TYPES = ['car', 'van', 'truck', 'bus'], CN = ['red', 'blue', 'yellow', 'green', 'purple', 'orange'], SIDES = ['x', 'y', 'xr', 'yb'];
const TOTAL = LEVEL_DB.length;
const RANKS = ['FACILE', 'MOYEN', 'DIFFICILE', 'IMPOSSIBLE', 'MANIAQUE'], RCOL = ['#35d44a', '#18c8ff', '#ff9f1c', '#ff2a44', '#b84dff'];
const rankIdx = slides => slides <= 3 ? 0 : slides <= 7 ? 1 : slides <= 11 ? 2 : slides <= 16 ? 3 : 4;   // rang = coups stratégiques minimum
const fmtT = s => s >= 60 ? Math.floor(s / 60) + ':' + String(Math.round(s % 60)).padStart(2, '0') : Math.round(s) + ' s';

function decode(n) {
  const [w, h, par, cs, bl, ps] = LEVEL_DB[(n - 1) % TOTAL];
  const cars = cs.map(a => ({ t: TYPES[a[0]], col: CN[a[1]], c: a[2], r: a[3], v: !!a[4], lock: a[5] ?? -1, ow: a[6] ?? 0, sl: a[7] ?? 0, ea: a[8] ?? -1, lc: a[9] ?? -1, ln: a[10] ?? 0 }));
  const portals = ps.map(a => ({ s: SIDES[a[0]], i: a[1], col: CN[a[2]], kind: a[3] || 0, p1: a[4] || 0, p2: a[5] || 0 }));
  const slides = par - cars.length, r = rankIdx(slides), est = 25 + 3 * cars.length + 9 * slides;
  const L = { n, w, h, par, slides, cars, blocks: bl, portals, rank: r, est };
  L.limit = Math.ceil(est * [2.2, 2, 1.8, 1.6, 1.5][r]);                                   // chrono (secondes)
  L.quota = Math.max(par + 3, Math.ceil(par * [2.2, 1.9, 1.7, 1.5, 1.4][r]));              // coups maximum autorisés
  L.mechs = MECHS.filter(m => m.test(L)).map(m => m.id);
  return L;
}
/* Niveau de première apparition de chaque mécanique (utile pour le design / un codex) */
function mechanicSchedule() {
  const first = {}; for (let n = 1; n <= TOTAL; n++) decode(n).mechs.forEach(id => { if (!(id in first)) first[id] = n; });
  return first;
}

/* ---------- 6c. ÉTAT DU JEU ---------- */
const board = $('board'), stage = $('stage');
let lv = null, levelNo = 1, cars = [], portals = [], blocks = [], W = 0, H = 0, cell = 60, moves = 0, history = [], startCount = 0, colTotal = [];
let gstate = 'idle', tLeft = 0, tLast = 0, tTimer = null;                    // idle | intro | playing | paused | over
const lenOf = car => LEN[car.t] / 60;
const snapshot = () => JSON.stringify(cars);
const exitedCount = () => startCount - cars.length;
const isAlive = id => cars.some(o => o.id === id);

/* ---------- 6d. RÈGLES (utilisées par le jeu ET vérifiées par le solveur) ---------- */
function isLocked(car) {
  if (car.lock >= 0 && isAlive(car.lock)) return true;                                       // cadenas : attend un véhicule précis
  if (car.lc >= 0 && cars.filter(o => CN.indexOf(o.col) === car.lc).length === colTotal[car.lc]) return true;   // cadenas couleur : aucun véhicule de cette couleur n'est sorti
  if (car.ln > 0 && exitedCount() < car.ln) return true;                                     // cadenas à compteur
  return false;
}
function portalFor(car, high) {
  const fixed = car.v ? car.c : car.r, side = car.v ? (high ? 'yb' : 'y') : (high ? 'xr' : 'x');
  return portals.find(p => p.s === side && p.i === fixed);
}
function portalOpen(p, car) {
  if (!p) return false;
  const ex = exitedCount(), ci = CN.indexOf(car.col), need = p.kind === 7 ? (CN.indexOf(p.col) + ex) % 6 : CN.indexOf(p.col);
  if (p.kind !== 1 && ci !== need) return false;
  switch (p.kind) {
    case 2: return ex >= p.p1;                         // givré
    case 3: return ex < p.p1;                          // éphémère
    case 4: return ex % 2 === p.p1;                    // pair / impair
    case 5: return ex >= p.p1 && ex <= p.p2;           // fenêtre
    case 6: return TYPES.indexOf(car.t) === p.p1;      // type
  }
  return true;
}
function limits(car) {
  const n = lenOf(car), size = car.v ? H : W, pos = car.v ? car.r : car.c, fixed = car.v ? car.c : car.r;
  if (isLocked(car)) return { lo: pos, hi: pos, min: pos, max: pos, exitLow: false, exitHigh: false, exitOK: false, locked: true };
  const taken = new Set(blocks.map(b => b[0] + ',' + b[1]));
  cars.forEach(o => { if (o.id !== car.id) for (let k = 0; k < lenOf(o); k++) taken.add((o.v ? o.c : o.c + k) + ',' + (o.v ? o.r + k : o.r)); });
  const free = p => p >= 0 && p < size && !taken.has((car.v ? fixed : p) + ',' + (car.v ? p : fixed));
  let lo = pos; while (free(lo - 1)) lo--;
  let hi = pos; while (free(hi + n)) hi++;
  const eaOK = !(car.ea >= 0 && isAlive(car.ea));                                              // priorité
  const exitLow = eaOK && lo === 0 && car.ow !== 1 && (!car.sl || pos <= car.sl) && portalOpen(portalFor(car, false), car);
  const exitHigh = eaOK && hi === size - n && car.ow !== -1 && (!car.sl || size - n - pos <= car.sl) && portalOpen(portalFor(car, true), car);
  let lo2 = lo, hi2 = hi;
  if (car.ow === -1) hi2 = pos; if (car.ow === 1) lo2 = pos;                                   // sens unique
  if (car.sl) { lo2 = Math.max(lo2, pos - car.sl); hi2 = Math.min(hi2, pos + car.sl); }        // véhicule lent
  return { lo: lo2, hi: hi2, min: exitLow ? -n : lo2, max: exitHigh ? size : hi2, exitLow, exitHigh, exitOK: exitLow || exitHigh };
}

/* ---------- 6e. FLUX D'UN NIVEAU : intro → tutoriels → partie ---------- */
function startLevel(n) {
  levelNo = n; lv = decode(n);
  W = lv.w; H = lv.h; portals = lv.portals; blocks = lv.blocks;
  cars = lv.cars.map((c, k) => ({ ...c, id: k })); startCount = cars.length;
  colTotal = CN.map(c => cars.filter(o => o.col === c).length);
  moves = 0; history = []; tLeft = lv.limit; gstate = 'intro';
  clearInterval(tTimer); closeOverlays();
  show('game');
  requestAnimationFrame(() => { draw(true); updateHud(); beginFlow(); });
}
function closeOverlays() { ['win', 'lose', 'intro', 'tuto', 'final'].forEach(id => { const e = $(id); if (e) e.id === 'win' ? e.classList.add('hidden') : e.remove(); }); }

function beginFlow() {
  const steps = [];
  if (lv.rank >= 2) steps.push(showIntro);                                                   // animation d'intro : DIFFICILE, IMPOSSIBLE, MANIAQUE
  lv.mechs.filter(id => !S.seen.includes(id)).forEach(id => steps.push(next => showTuto(id, next)));
  const run = () => { const f = steps.shift(); f ? f(run) : startTimer(); };
  setTimeout(run, 450);
}
function showIntro(next) {
  const r = lv.rank, d = document.createElement('div'); d.id = 'intro';
  d.style.setProperty('--rc', RCOL[r]);
  d.innerHTML = `<div class="icard"><div class="ilvl">NIVEAU ${lv.n}</div><div class="irank">${RANKS[r]}</div>
    <div class="idur">⏱ Durée cible ${fmtT(lv.est * .8)} – ${fmtT(lv.est * 1.2)}</div>
    <div class="idur">🎯 Maximum ${lv.quota} coups · ${fmtT(lv.limit)} au chrono</div>
    <div class="imech">${lv.mechs.map(id => MECHS.find(m => m.id === id).icon).join(' ')}</div><small>Touche pour commencer</small></div>`;
  app.appendChild(d); vib([30, 40, 60]);
  let done = false; const go = () => { if (done) return; done = true; d.classList.add('out'); setTimeout(() => { d.remove(); next(); }, 300); };
  d.onclick = go; setTimeout(go, 2600);
}
function showTuto(id, next) {
  const m = MECHS.find(x => x.id === id), d = document.createElement('div'); d.id = 'tuto';
  d.innerHTML = `<div class="tcard"><div class="tnew">NOUVEAU !</div><div class="tart">${m.art}</div><h3>${m.icon} ${m.name}</h3><p>${m.text}</p>
    <button class="play small press">COMPRIS !</button></div>`;
  app.appendChild(d); vib(20);
  d.querySelector('button').onclick = () => { S.seen.push(id); save(); d.remove(); next(); };
}

/* ---------- 6f. CHRONO ---------- */
function startTimer() { gstate = 'playing'; tLast = performance.now(); clearInterval(tTimer); tTimer = setInterval(tick, 200); updateHud(); }
function tick() {
  if (gstate !== 'playing') return;
  const now = performance.now(); tLeft -= (now - tLast) / 1000; tLast = now;
  const sec = Math.ceil(tLeft); if (sec <= 10 && sec !== tick.last) { tick.last = sec; if (sec > 0) SFX.tick(); }   // tic-tac des 10 dernières secondes
  if (tLeft <= 0) { tLeft = 0; updateHud(); lose('time'); } else updateHud();
}
document.addEventListener('visibilitychange', () => { if (document.hidden && gstate === 'playing') gstate = 'paused'; else if (!document.hidden && gstate === 'paused') { gstate = 'playing'; tLast = performance.now(); } });
function updateHud() {
  if (!lv) return;
  let gi = $('ginfo'); if (!gi) { gi = document.createElement('div'); gi.id = 'ginfo'; document.querySelector('#game .gtop').after(gi); }
  gi.textContent = `🎯 Cible ${fmtT(lv.est * .8)} – ${fmtT(lv.est * 1.2)} · optimum ${lv.par} coups`;
  $('lvl').innerHTML = `NIVEAU ${lv.n} <b class="rk" style="background:${RCOL[lv.rank]}">${RANKS[lv.rank]}</b>`;
  $('moves').textContent = `${moves}/${lv.quota} coups`; $('moves').classList.toggle('low', lv.quota - moves <= 2);
  const g = $('gcoins'); g.textContent = '⏱ ' + fmtT(Math.ceil(tLeft)); g.classList.toggle('low', tLeft <= 15);
}

/* ---------- 6g. AFFICHAGE ---------- */
function paintPortal(d, p) {
  const ex = exitedCount(), c = COL[CN[p.kind === 7 ? (CN.indexOf(p.col) + ex) % 6 : CN.indexOf(p.col)]], horiz = p.s === 'x' || p.s === 'xr';
  let open = true, text = '';
  switch (p.kind) {
    case 1: text = '⭐'; break;
    case 2: open = ex >= p.p1; text = open ? '' : '❄' + (p.p1 - ex); break;
    case 3: open = ex < p.p1; text = open ? '⏳' + (p.p1 - ex) : '✖'; break;
    case 4: open = ex % 2 === p.p1; text = p.p1 ? 'IMP' : 'PAIR'; break;
    case 5: open = ex >= p.p1 && ex <= p.p2; text = p.p1 + '-' + p.p2; break;
    case 6: text = ['🚗', '🚐', '🚚', '🚌'][p.p1]; break;
    case 7: text = '🌈'; break;
  }
  d.className = 'portal' + (p.kind === 1 ? ' star' : '') + (open ? '' : ' shut');
  d.style.background = p.kind === 1 ? `conic-gradient(${Object.values(COL).join(',')},${COL.red})`
    : `linear-gradient(${{ x: '90deg', xr: '270deg', y: '180deg', yb: '0deg' }[p.s]}, ${mx(c, .3)}, ${c})`;
  d.style.boxShadow = `0 0 ${cell * .35}px ${p.kind === 1 ? '#fff' : c}`; d.textContent = text;
}
function updatePortals() { board.querySelectorAll('.portal').forEach(d => { const was = d.classList.contains('shut'); paintPortal(d, d._p); if (was && !d.classList.contains('shut')) { toast('🚪 Un portail s\'ouvre !'); vib(25); SFX.ping(); } }); }

function draw(fresh = true) {
  cell = Math.floor(Math.min((stage.clientWidth - 60) / W, (stage.clientHeight - 60) / H, 80));
  board.style.width = W * cell + 'px'; board.style.height = H * cell + 'px'; board.style.setProperty('--cell', cell + 'px');
  board.innerHTML = '';
  for (let x = 0; x < W; x++) for (let y = 0; y < H; y++) {
    const t = document.createElement('div'); t.className = 'tile';
    t.style.cssText = `left:${x * cell + 2}px;top:${y * cell + 2}px;width:${cell - 4}px;height:${cell - 4}px;background:${(x + y) % 2 ? '#1b3680' : '#203d92'}`;
    board.appendChild(t);
  }
  blocks.forEach(([bx, by]) => {
    const d = document.createElement('div'); d.className = 'block';
    d.style.cssText = `left:${bx * cell + 3}px;top:${by * cell + 3}px;width:${cell - 6}px;height:${cell - 6}px`; board.appendChild(d);
  });
  portals.forEach(p => {
    const d = document.createElement('div'), a = cell * .76, b = cell * .4, horiz = p.s === 'x' || p.s === 'xr';
    const off = { x: `left:${-b - cell * .08}px;top:${p.i * cell + cell * .12}px`, xr: `left:${W * cell + cell * .08}px;top:${p.i * cell + cell * .12}px`,
                  y: `top:${-b - cell * .08}px;left:${p.i * cell + cell * .12}px`, yb: `top:${H * cell + cell * .08}px;left:${p.i * cell + cell * .12}px` }[p.s];
    d.style.cssText = `${off};width:${horiz ? b : a}px;height:${horiz ? a : b}px;font-size:${cell * .22}px;border-radius:${cell * .2}px`;
    d._p = p; paintPortal(d, p); board.appendChild(d);
  });
  cars.forEach((car, i) => makeVehicle(car, fresh ? i * .08 : 0, fresh));
  updateHud();
}
function place(el, car, pos) { const x = car.v ? car.c : pos, y = car.v ? pos : car.r; el.style.transform = `translate(${x * cell}px, ${y * cell}px)`; }

/* Pastilles : cadenas, compteurs, sens unique, lent, priorité */
function badgesHTML(car) {
  const dot = c => `<u style="background:${COL[CN[c]] || c}"></u>`; let h = '';
  if (car.lock >= 0 && isAlive(car.lock)) h += `<div class="lock"><b>🔒</b>${dot(CN.indexOf(cars.find(o => o.id === car.lock).col))}</div>`;
  else if (car.lc >= 0 && isLocked(car)) h += `<div class="lock"><b>🔒</b>${dot(car.lc)}</div>`;
  else if (car.ln > 0 && isLocked(car)) h += `<div class="lock"><b>🔒</b><i class="num">${car.ln - exitedCount()}</i></div>`;
  let tags = '';
  if (car.ow) tags += car.v ? (car.ow < 0 ? '⬆' : '⬇') : (car.ow < 0 ? '⬅' : '➡');
  if (car.sl) tags += '🐢';
  if (car.ea >= 0 && isAlive(car.ea)) tags += '🎯' + dot(CN.indexOf(cars.find(o => o.id === car.ea).col));
  return h + (tags ? `<div class="tag">${tags}</div>` : '');
}
function makeVehicle(car, delay, pop) {
  const n = lenOf(car), el = document.createElement('div');
  el.className = 'veh'; el.dataset.id = car.id;
  el.style.width = (car.v ? 1 : n) * cell + 'px'; el.style.height = (car.v ? n : 1) * cell + 'px';
  el.innerHTML = `<div class="in ${pop ? 'pop' : ''}" style="--dl:${delay}s"><svg viewBox="0 0 ${LEN[car.t]} 60" width="${n * cell}" height="${cell}"
    style="${car.v ? `transform:translateX(${cell}px) rotate(90deg);transform-origin:0 0` : ''}">${vehicleSVG(car.t, car.col)}</svg><div class="bdg">${badgesHTML(car)}</div></div>`;
  place(el, car, car.v ? car.r : car.c);
  if (isLocked(car)) el.classList.add('islocked');
  const inn = el.firstChild;
  inn.addEventListener('animationend', ev => { if (ev.animationName === 'popin') { inn.classList.remove('pop'); updateFree(); } });
  el.addEventListener('pointerdown', e => startDrag(e, car, el));
  board.appendChild(el);
  if (!pop) updateFree();
}
function refreshBadges() {                                          // après chaque sortie : cadenas, compteurs, priorités, portails
  board.querySelectorAll('.veh').forEach(el => {
    const car = cars.find(c => c.id === +el.dataset.id); if (!car) return;
    const was = el.classList.contains('islocked'), now = isLocked(car);
    el.querySelector('.bdg').innerHTML = badgesHTML(car);
    if (was && !now) { el.classList.remove('islocked'); toast('🔓 Véhicule débloqué !'); vib(30); SFX.unlock(); el.firstChild.classList.add('unlocked'); setTimeout(() => el.firstChild.classList.remove('unlocked'), 600); }
  });
  updatePortals();
}
function updateFree() {
  cars.forEach(car => {
    const el = board.querySelector(`[data-id="${car.id}"]`); if (!el) return;
    const inn = el.firstChild; if (inn.classList.contains('pop') || inn.classList.contains('bounce')) return;
    inn.classList.toggle('free', limits(car).exitOK);
  });
}

/* ---------- 6h. GLISSER-DÉPOSER ---------- */
function shakeLocked(el, car) {
  const inn = el.firstChild; inn.classList.remove('shake'); void inn.offsetWidth; inn.classList.add('shake');
  setTimeout(() => inn.classList.remove('shake'), 400); vib(40);
  toast(car.lock >= 0 ? '🔒 Fais d\'abord sortir le véhicule de la pastille' : car.lc >= 0 ? '🔒 Fais sortir un véhicule de la couleur de la pastille' : `🔒 Il faut encore ${car.ln - exitedCount()} sortie(s)`);
}
function startDrag(e, car, el) {
  e.preventDefault();
  if (gstate !== 'playing') return;
  if (isLocked(car)) { shakeLocked(el, car); return; }
  SFX.grab();
  el.setPointerCapture(e.pointerId); el.classList.add('drag'); el.firstChild.classList.remove('free');
  const lim = limits(car), n = lenOf(car), size = car.v ? H : W, start = car.v ? car.r : car.c, x0 = car.v ? e.clientY : e.clientX;
  let pos = start;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const move = ev => { pos = clamp(start + ((car.v ? ev.clientY : ev.clientX) - x0) / cell, lim.min, lim.max); place(el, car, pos); };
  const up = () => {
    el.removeEventListener('pointermove', move); el.removeEventListener('pointerup', up); el.removeEventListener('pointercancel', up);
    el.classList.remove('drag');
    if (lim.exitLow && pos <= -n * 0.55) return leave(car, el, n, false);
    if (lim.exitHigh && pos >= size - n * 0.45) return leave(car, el, n, true);
    const snap = clamp(Math.round(pos), lim.lo, lim.hi);
    place(el, car, snap); bounce(el);
    if (snap !== start) {
      history.push(snapshot()); if (car.v) car.r = snap; else car.c = snap;
      moves++; vib(12); SFX.slide(Math.abs(snap - start)); updateHud(); checkQuota();
    }
    setTimeout(updateFree, 400);
  };
  el.addEventListener('pointermove', move); el.addEventListener('pointerup', up); el.addEventListener('pointercancel', up);
}
function checkQuota() { if (gstate === 'playing' && moves > lv.quota) lose('moves'); }

function leave(car, el, n, high) {
  history.push(snapshot()); moves++;
  const px = car.v ? (car.c + .5) * cell : (high ? W * cell : 0), py = car.v ? (high ? H * cell : 0) : (car.r + .5) * cell;
  place(el, car, high ? (car.v ? H : W) + 1 : -n - 1); el.classList.add('out');
  cars = cars.filter(c => c.id !== car.id);
  refreshBadges();
  setTimeout(() => el.remove(), 320);
  burst(px, py, COL[car.col]); floatText(px, py, '+5 🪙'); SFX.pop();
  S.coins += 5; save(); refreshHud(); vib([20, 30, 20]); updateHud();
  setTimeout(updateFree, 350);
  if (!cars.length) { if (moves <= lv.quota) setTimeout(win, 600); else lose('moves'); } else checkQuota();
}

/* ---------- 6i. VICTOIRE (score %, étoiles) & DÉFAITE ---------- */
function win() {
  if (gstate === 'over') return; gstate = 'over'; clearInterval(tTimer);
  const mEff = Math.min(1, lv.par / Math.max(1, moves));                                          // écart avec le nombre de coups optimal
  const tEff = Math.max(0, Math.min(1, tLeft / Math.max(1, lv.limit - lv.est * .5)));              // temps restant
  const score = Math.round(100 * (.6 * mEff + .4 * tEff)), stars = score >= 90 ? 3 : score >= 65 ? 2 : 1;
  const old = S.best[levelNo] || { score: 0, stars: 0 };
  S.best[levelNo] = { score: Math.max(old.score, score), stars: Math.max(old.stars, stars) };
  const gain = 10 + 10 * stars; S.coins += gain; if (levelNo >= S.level) S.level = levelNo + 1; save(); refreshHud(); vib([40, 40, 80]); confetti(40 + stars * 20); SFX.win(stars);
  if (levelNo >= TOTAL) return setTimeout(showFinal, 700);
  document.querySelector('#win h2').textContent = score >= 90 ? 'PARFAIT !' : 'NIVEAU TERMINÉ !';
  document.querySelector('#win .stars').innerHTML = [0, 1, 2].map(i => `<span class="st ${i < stars ? 'on' : ''}" style="--i:${i}">${i < stars ? '⭐' : '☆'}</span>`).join('');
  $('winInfo').innerHTML = `<b class="score">${score} %</b><br>${moves}/${lv.quota} coups (optimal ${lv.par}) · ⏱ ${fmtT(lv.limit - tLeft)}<br>+${gain} 🪙`;
  $('win').classList.remove('hidden');
}
function lose(reason) {
  if (gstate === 'over') return; gstate = 'over'; clearInterval(tTimer); vib([80, 40, 120]); SFX.lose();
  const d = document.createElement('div'); d.id = 'lose';
  d.innerHTML = `<div class="lcard"><div class="boom">${reason === 'time' ? '⏰' : '💥'}</div><h2>${reason === 'time' ? 'TEMPS ÉCOULÉ !' : 'TROP DE COUPS !'}</h2>
    <p>${reason === 'time' ? 'Le chrono est arrivé à zéro.' : `Tu as dépassé le quota de ${lv.quota} coups.`}</p>
    <button class="play small press" id="lRetry">RÉESSAYER (−1 ❤️)</button><button class="play small alt press" id="lHome">ACCUEIL</button></div>`;
  app.appendChild(d);
  $('lRetry').onclick = retry; $('lHome').onclick = () => { closeOverlays(); show('home'); };
}
function retry() {
  tickLives();
  if (S.lives < 1) return toast('Plus de vie ! Attends ou va en boutique ❤️');
  S.lives--; if (!S.next) S.next = Date.now() + REGEN * 1000; save(); tickLives(); startLevel(levelNo);
}

/* ---------- 7. JUICE (effets visuels) ---------- */
function bounce(el) {
  const inn = el.firstChild; inn.classList.remove('bounce'); void inn.offsetWidth; inn.classList.add('bounce');
  inn.addEventListener('animationend', () => inn.classList.remove('bounce'), { once: true });
}
function burst(x, y, color) {                                       // étincelles à la sortie
  for (let i = 0; i < 14; i++) {
    const s = document.createElement('i'); s.className = 'spark';
    s.style.cssText = `left:${x}px;top:${y}px;background:${i % 3 ? color : '#fff'};--x:${(Math.random() - .5) * 150}px;--y:${(Math.random() - .5) * 150}px`;
    board.appendChild(s); setTimeout(() => s.remove(), 750);
  }
}
function floatText(x, y, txt) {
  const t = document.createElement('div'); t.className = 'pop-txt'; t.textContent = txt;
  t.style.left = Math.max(0, x - 20) + 'px'; t.style.top = Math.max(0, y - 10) + 'px';
  board.appendChild(t); setTimeout(() => t.remove(), 950);
}
function confetti(n) {
  for (let i = 0; i < n; i++) {
    const c = document.createElement('i'); c.className = 'confetti';
    c.style.cssText = `left:${Math.random() * 100}%;background:${Object.values(COL)[i % 6]};animation-delay:${Math.random() * .6}s;animation-duration:${1.6 + Math.random()}s`;
    app.appendChild(c); setTimeout(() => c.remove(), 3000);
  }
}

/* ---------- 7b. BOUTONS, ÉCRAN FINAL, CSS ---------- */
$('btnUndo').onclick = () => { if (gstate !== 'playing') return; if (!history.length) return toast('Rien à annuler'); cars = JSON.parse(history.pop()); moves = Math.max(0, moves - 1); draw(false); };
$('btnHint').onclick = () => {
  if (gstate !== 'playing') return;
  const car = cars.find(c => limits(c).exitOK), el = car && board.querySelector(`[data-id="${car.id}"]`);
  if (el) { el.classList.remove('hint'); void el.offsetWidth; el.classList.add('hint'); } else toast('Aucun véhicule ne peut sortir : déplace-en un !');
};
$('btnRestart').onclick = () => { if (gstate === 'intro') return; retry(); };
$('btnHome').onclick = () => show('home');
$('btnNext').onclick = () => startLevel(levelNo + 1);
$('play').onclick = () => { vib(15); startLevel(S.level > TOTAL ? 1 : S.level); };
addEventListener('resize', () => { if (current === 'game' && lv) draw(false); });

function showFinal() {
  const f = document.createElement('div'); f.id = 'final';
  f.innerHTML = `<div class="fcard"><div class="trophy">🏆</div><h2>FÉLICITATIONS !</h2>
    <p>Tu as terminé les <b>${TOTAL} niveaux</b> de Traffic Color Sort !</p><div class="fcoins">🪙 ${S.coins}</div>
    <button class="play small press" id="fReplay">REJOUER</button><button class="play small alt press" id="fHome">ACCUEIL</button></div>`;
  app.appendChild(f); confetti(120); setTimeout(() => confetti(80), 900);
  $('fReplay').onclick = () => { f.remove(); startLevel(1); };
  $('fHome').onclick = () => { f.remove(); show('home'); };
}

